#!/usr/bin/env python3
"""Freeze L11 source-first answers; never read keyed authored data here."""
import datetime,hashlib,json
from pathlib import Path
R=Path(__file__).resolve().parents[1];p=R/'audits/blind-W03-L11-review-copy.json';b=json.loads(p.read_text());assert b['sourcePacketSha256']=='fb57edcef1a3928aa2d514b1a20b776a6f9d7290fd0fbf3a1fe3c7b812fdc3b5'
reasons={
355:['Rigid-body idealization preserves all pairwise distances, not world coordinates or zero force.','A free spatial rigid body has three translational and three rotational local freedoms.','Joints allow relative poses to change while each link retains its own shape.'],
356:['The source names motion-to-required-torque calculation inverse dynamics.','The source explicitly pairs inverse dynamics with control and forward dynamics with simulation.','A torque history requires a dynamic model and state/initial conditions to determine motion; external forces and other modeled effects also matter.'],
357:['Acceleration is the time derivative of velocity, represented by its difference quotient.','The shorthand differentiates motion of A origin relative to U; it is not necessarily the COM.','Differentiate componentwise: (2t,3,0); t=2 gives (4,3,0) m/s².','Linear acceleration has units m/s² and angular acceleration rad/s².'],
358:['Differentiate Rq twice using Rdot x=omega cross Rx: a_rel+2 omega cross v_rel+alpha cross r+omega cross (omega cross r).','One omega cross v_rel comes from differentiating R v_B and another from differentiating omega cross Rq_B.','The twice-relative-velocity cross term is Coriolis, alpha cross r is tangential, and the nested omega cross is centripetal.','The fixed body point has no relative motion or angular acceleration; omega cross (omega cross r)=(-12,0,0).','For a body-fixed offset at this instant with omega=0, only alpha cross r remains: (0,0,3) cross (2,0,0)=(0,6,0). The stem should explicitly say fixed in B rather than fixed r.','The Coriolis term vanishes with zero relative velocity, zero omega, or parallel relative velocity and omega. Zero alpha alone does not eliminate it.','Centripetal=(-18,0,0), tangential=(0,4,0), Coriolis=(0,6,0); total=(-18,10,0).','A fixed point has no relative acceleration or Coriolis term. Parallel omega and r make the nested cross zero; alpha=0 eliminates tangential acceleration.'],
359:['The position chain includes A-to-B-origin displacement, whose second derivative adds origin acceleration a0.','Constant q_B for all time implies both B-relative first and second derivatives vanish; transport and origin terms can remain.','Centripetal=(-8,0,0), tangential=(0,2,0), origin=(1,2,0); sum=(-7,4,0).','The general equation includes the fixed-point specialization. The joint labels describe useful applications, not disjoint mathematical validity domains.','Nonrotation eliminates all rotational terms, leaving a0+a_rel=(2,3,0).'],
360:['Differentiate omega_AC=omega_AB+R_AB omega_BC: alpha_AB+R alpha_BC+omega_AB cross (R omega_BC). There is one transport cross term.','At the stated instant R=I, the cross term (0,0,2) cross (3,0,0)=(0,6,0) remains despite zero relative angular accelerations.','Parallel angular-velocity vectors have zero cross product after matching bases. Coincident origins or zero angular accelerations do not ensure this.','R alpha_BC=(0,2,0), R omega_BC=(0,3,0), omega_AB cross that=(-3,0,0). Adding alpha_AB=(1,0,0) gives (-2,2,0).'],
361:['Arbitrary-axis rotation requires the full inertia tensor relative to an origin and orientation, not merely total mass or one scalar moment.','The source matrix places minus the raw xy product off diagonal, so I12=-Pxy.','A symmetric 3-by-3 array has three diagonal and three independent off-diagonal entries.','Negating each raw product gives (-2,3,0) kg·m².','Inertia entries have mass-times-length-squared units; their tensor is symmetric; scalar mass alone cannot specify mass spread. Changing coordinates does not alter total mass.'],
362:['Perpendicular squared distance from x is y²+z², so integrate that against rho dV.','Density is mass per volume, so differential mass equals rho dV.','For m=2 and (1,2,3), moments are 2(4+9)=26, 2(1+9)=20 and 2(1+4)=10.','Raw products mxy,mxz,myz give (4,6,12) kg·m²; signed entries are their negatives.','On the x axis, y=z=0, making the perpendicular squared distance and Ixx contribution zero.','mxy is negative when x>0,y<0,m>0; the matrix entry is its negative and therefore positive.'],
363:['Principal directions diagonalize the symmetric tensor about the specified origin; all off-diagonal products vanish.','Both translating the reference origin and rotating axes can change inertia components, although neither changes total mass.','In an explicitly principal diagonal tensor the diagonal numbers are the principal moments 2,3,4.','Choosing orientation cannot remove dependence on the reference origin; every inertia tensor and its eigenstructure refers to an origin.'],
364:['The composite COM is the mass-weighted position average, total first moment divided by total mass.','(2*0+1*3)/(2+1)=1 m.','Uniform density lets density cancel from the volume-weighted COM integral, leaving the geometric volume centroid.','A point mass at the COM preserves total mass and translational resultant behavior, but loses the spread that determines rotational inertia.','(1*(0,0,0)+3*(2,4,0))/4=(1.5,3,0) m.'],
365:['The drawn axes and integration bounds give x width w, y length l and z height h.','For the corner origin integrate (y²+z²) rho over x in [0,w], y in [0,l], z in [0,h].','The integrand is independent of x; integrating x contributes a factor w.','m/3=4; diagonal moments are 4(16+36)=208, 4(4+36)=160 and 4(4+16)=80.','Ixx=m(l²+h²)/3 has no width dependence at fixed mass, l and h; changing width alters density under this premise.'],
366:['Integrating xy over positive box coordinates gives rho*(w²/2)*(l²/2)*h=mwl/4.','The signed entries are -mwl/4=-24, -mwh/4=-36 and -mlh/4=-72.','A symmetric geometric box can have nonzero products about a corner: its coordinate integration intervals are not symmetric around zero.'],
367:['The slide names symmetry and positive definiteness as constraints; the nondegenerate-solid premise excludes zero-moment ideal line/point distributions.','Calling a model physics-informed does not impose a mathematical constraint; architecture, parameterization or explicit enforcement must actually enforce it.','Adding the first two diagonal integral expressions and subtracting the third leaves 2 integral z² dm, nonnegative for nonnegative mass.'],
368:['The COM-to-translated-origin correction is m[(p dot p)I-pp transpose], added to the COM tensor in the same orientation.','Distance to a parallel z axis depends on transverse x and y coordinates, so its squared shift is xc²+yc².','p dot p=14; subtract outer product from 14I and multiply by 2 to get [[26,-4,-6],[-4,20,-12],[-6,-12,10]].','COM first moments vanish. The raw product gains mxc yc, while its negative signed tensor entry loses mxc yc.','p362 defines Ixy as positive raw integral, but p368 uses a negative shift and p369 substitutes a negative corner value. The scalar symbol has switched to signed-entry meaning; the matrix theorem remains consistent.','Tensors and p must be expressed in common target axes before addition. Translation is not a substitute for orientation conversion.','For p=(0,0,d), (p dot p)I-pp transpose=diag(d²,d²,0); no off-diagonal changes.','Robot rotation axes may be displaced from link COMs, so a COM inertia needs a reference-axis shift.'],
369:['Uniformity and rectangular bounds put the centroid halfway along each side: (w/2,l/2,h/2).','Subtract the COM offset correction m(w²+l²)/4 from the corner moment m(w²+l²)/3 to leave m(w²+l²)/12.','From I12,A=I12,C-mwl/4 and I12,A=-mwl/4, the centered I12,C is zero.'],
370:['At COM the factor is m/12=1 and symmetry kills products, giving diag(52,40,20).','For equal sides each diagonal is m(a²+a²)/12=ma²/6, with zero products.','The central normal z moment uses the two in-plane squared sides, m(w²+l²)/12, and does not vanish with thickness.'],
371:['The table prints 2mR²/5 for a uniform solid sphere about a central diameter.','The rod formula mL²/12 is about a center-crossing axis perpendicular to its length.','Central moment is 3*2²/12=1; end shift adds 3*(2/2)²=3, totaling 4 kg·m².','Thin shell mR² divided by solid cylinder mR²/2 gives 2 for matched radius and mass.','mR² treats all shell mass at radius R; a general thick annulus does not have one radius for all its mass.','The sum of both in-plane side squares corresponds to the plate normal through its center, not every central axis.','6*(2²+4²)/12=10 kg·m².'],
372:['A mass element contributes m times squared perpendicular axis distance; distal placement can magnify rotational inertia.','2*.6²=.72 and 2*.3²=.18, a .54/.72=.75 or 75 percent reduction.','The source explicitly names batteries, actuators and counterweights.','Mass placement can aim for favorable COM behavior, but a guarantee across all articulated configurations requires configuration-dependent analysis.','The source describes reducing mass while maintaining stiffness using hollow, beam, lattice and topology-optimized forms.'],
373:['Appropriate symmetry cancels relevant raw products in chosen coordinates, simplifying off-diagonal coupling without eliminating mass or diagonal moments.','The source proposes matching motor and load inertia, with gear ratios changing the compared/reflected drive coordinates. This is source-specific heuristic recall.','Universal power-transfer efficiency cannot follow from bare inertia equality; drive coordinates, gear losses, dynamics and optimization objective matter.','Distal inertia reduction can help acceleration under comparable actuation, but stability depends on task, support, geometry and motion constraints.'],
374:['Reflection through the xy plane pairs z with -z, cancelling xz and yz integrals, while xy is unchanged.','One xy symmetry plane does not force Pxy to vanish because xy is even under z sign reversal.','The moment integral is nonnegative, with zero possible when all mass lies on the axis; a nondegenerate volumetric solid has positive moments.','The sum of diagonal entries is the trace, invariant under pure orientation change at the same origin.','Trace conservation gives third moment 14-4-6=4 kg·m².','Trace of m[(p dot p)I-pp transpose] is 2m|p|²=2*2*9=36 kg·m².','Eigenvalues are principal moments and eigenvectors give principal-axis directions about that origin.','Multiplying I by (1,1,0)/sqrt(2) returns three times that vector; the anti-symmetric xy direction has eigenvalue 1 and z has 4.','The source gives an inertia pendulum as a practical measurement example.','The course offers both physical measurement and CAD-based mass-property calculation; the practical-measurement sentence cannot prohibit the later suggested calculation.'],
375:['The XML mass attribute is 1.5 and its inertial origin xyz is 0 0 0.15 relative to the link.','The inertial origin marks the COM location relative to the link frame.','The three nonzero diagonal entries are .003,.003,.001; all three displayed off-diagonal entries are zero.','The particular encoded tensor is diagonal, so its inertial coordinate axes are principal axes. This does not make arbitrary URDF diagonals principal values.','Offset correction is 1.5*.15²=.03375 on x and y, none on z. Adding COM tensor gives diag(.03675,.03675,.001).','The z principal moment .001 is smaller than x and y at .003.','The bottom source recommendation is SolidWorks/CAD mass-property calculation with a URDF export plugin; this is not an availability guarantee.','ElementTree attributes are strings; the nested inertia attribute izz is the literal string 0.001, not a float.'],
376:['The summary retains relative, Coriolis, tangential and centripetal terms but omits the separated-origin acceleration present on p359.','The omitted vector term must be zero for that shortened equation to agree with the full formula under otherwise identical quantities.']}
answers=[]
for q in b['questions']:
 page=int(q['id'].split('-P')[1][:4]);idx=int(q['id'].rsplit('Q',1)[1])-1
 ans=['o1','o2','o3'] if q['id'] in ['W03-L11-P0358-Q06','W03-L11-P0361-Q05'] else ['o1']
 answers.append({'questionId':q['id'],'questionVersion':q['version'],'independentAnswerOptionIds':ans,'reasoning':reasons[page][idx],'reviewedSlideIds':[c['slideId'] for c in q['citations']],'blindItemSha256':hashlib.sha256(json.dumps(q,sort_keys=True,separators=(',',':'),ensure_ascii=False).encode()).hexdigest()})
assert len(answers)==sum(map(len,reasons.values()))==108
out={'reviewerId':'build_offline_study_interface-L11-independent','frozenAt':datetime.datetime.now(datetime.timezone.utc).isoformat(),'complete':True,'solvedBeforeAnswerSeen':True,'keyedBatchOpened':False,'sourcePacketPath':b['sourcePacketPath'],'sourcePacketSha256':b['sourcePacketSha256'],'reviewCopyPath':str(p.relative_to(R)),'reviewCopySha256':hashlib.sha256(p.read_bytes()).hexdigest(),'sourcePagesInspected':list(range(352,379)),'sourceInspectionMethod':'Read all 27 actual 1800x1013 page images at readable scale, including equations, diagram axes, box integration limits, table entries, XML and captions, alongside full extracted page text. No keyed question batch or author dispute ledger opened.','answers':answers,'sourceNotes':['Raw xy-product notation changes to signed-entry convention between p362 and p368/p369, and the p376 summary juxtaposes both conventions.','The p376 generalized-acceleration heading omits origin acceleration present on p359; it is valid only under the additional zero-origin-acceleration condition.','The cylinder/plate table needs shell/axis qualifications. Positive inertia claims need nondegenerate-solid versus idealized-distribution scope. Universal COM/stability/inertia-matching and physics-informed enforcement statements require bounded interpretations.']}
t=R/'audits/blind-answers-W03-L11-independent.json';assert not t.exists();t.write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n');print('Frozen',len(answers),'answers',out['frozenAt'])
